-- Create "workflow_settings" table
CREATE TABLE "workflow_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "content_types" jsonb NULL, "lock_minutes" bigint NOT NULL DEFAULT 30, PRIMARY KEY ("id"));
-- Create "workflow_states" table
CREATE TABLE "workflow_states" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "machine_name" character varying NOT NULL, "label" character varying NOT NULL, "published" boolean NOT NULL DEFAULT false, "color" character varying NOT NULL DEFAULT 'gray', "initial" boolean NOT NULL DEFAULT false, "weight" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create index "workflow_states_machine_name" to table: "workflow_states"
CREATE UNIQUE INDEX "workflow_states_machine_name" ON "workflow_states" ("machine_name");
-- Create "workflow_transitions" table
CREATE TABLE "workflow_transitions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "from_states" jsonb NOT NULL, "to_state" character varying NOT NULL, "label" character varying NOT NULL, "roles" jsonb NOT NULL, "comment" character varying NOT NULL DEFAULT 'optional', "weight" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create "workflow_history" table
CREATE TABLE "workflow_history" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "from_state" character varying NOT NULL, "to_state" character varying NOT NULL, "uid" bigint NOT NULL DEFAULT 0, "comment" text NOT NULL, "created_at" timestamptz NOT NULL, "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "workflow_history_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "workflow_history_nid" to table: "workflow_history"
CREATE INDEX "workflow_history_nid" ON "workflow_history" ("nid", "created_at");
-- Create "workflow_locks" table
CREATE TABLE "workflow_locks" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "uid" bigint NOT NULL, "locked_at" timestamptz NOT NULL, "touched_at" timestamptz NOT NULL, "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "workflow_locks_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "workflow_locks_nid" to table: "workflow_locks"
CREATE UNIQUE INDEX "workflow_locks_nid" ON "workflow_locks" ("nid");
-- Create "workflow_node_states" table
CREATE TABLE "workflow_node_states" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "state" character varying NOT NULL, "changed_at" timestamptz NOT NULL, "changed_by" bigint NOT NULL DEFAULT 0, "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "workflow_node_states_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "workflow_node_states_nid" to table: "workflow_node_states"
CREATE UNIQUE INDEX "workflow_node_states_nid" ON "workflow_node_states" ("nid");
-- Create index "workflow_node_states_state" to table: "workflow_node_states"
CREATE INDEX "workflow_node_states_state" ON "workflow_node_states" ("state", "changed_at");
